// QA-only worker import generated by Vite. No Cache Storage or commercial JWT.
export function createQaPushObservationWorker({ workerBuild, workerRevision, fetch: send, crypto, now = Date.now, timeoutMs = 1500 }) {
  const endpoint = 'https://zipco-backend-qa.up.railway.app/qa/push-observations/events';
  const contract = 'qa-push-observation-v1';
  const uuid = value => typeof value === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(value);
  const enabled = /^[a-f0-9]{40}$/.test(workerBuild || '') && workerRevision === 'notification-click-attempt-v11';
  const stages = new Set(['PUSH_RECEIVED','SYSTEM_SHOWN','CLICK_RECEIVED','TARGET_NORMALIZED','LAUNCH_REQUESTED','NAVIGATION_POSTED','CLICK_FAILED','APP_TARGET_ACCEPTED','CARD_FOCUSED']);
  const events = new WeakMap(), contexts = new WeakMap(), clicks = new Map(), stopped = new Map();
  const prune = () => {
    for (const [id, ctx] of clicks) if (Date.parse(ctx.block.expiresAt) <= now()) clicks.delete(id);
    for (const [id, expires] of stopped) if (expires <= now()) stopped.delete(id);
  };
  const parse = value => {
    if (!enabled || !value || typeof value !== 'object' || Array.isArray(value)) return null;
    if (value.contract !== contract || !uuid(value.traceId) || value.reportUrl !== endpoint ||
        typeof value.receiptToken !== 'string' || !/^[A-Za-z0-9_-]{43}$/.test(value.receiptToken) ||
        typeof value.expiresAt !== 'string' || !/^\d{4}-\d\d-\d\dT.*Z$/.test(value.expiresAt) ||
        !Number.isFinite(Date.parse(value.expiresAt)) || Date.parse(value.expiresAt) <= now()) return null;
    prune();
    if (stopped.has(value.traceId)) return null;
    return { contract, traceId: value.traceId, reportUrl: endpoint, receiptToken: value.receiptToken, expiresAt: value.expiresAt };
  };
  const begin = (event, value, kind) => {
    const block = parse(value);
    if (!block) return null;
    let attemptId;
    try { attemptId = crypto?.randomUUID?.(); } catch { return null; }
    if (!uuid(attemptId)) return null;
    const ctx = { block, attemptId, kind, sent: new Set(), clients: new Set(), target: null };
    contexts.set(event, ctx);
    if (kind === 'click') {
      clicks.set(attemptId, ctx);
      if (clicks.size > 100) clicks.delete(clicks.keys().next().value);
    }
    return ctx;
  };
  const report = (event, ctx, stage, flags = {}) => {
    if (!ctx || !stages.has(stage) || ctx.sent.has(stage) || stopped.has(ctx.block.traceId) || Date.parse(ctx.block.expiresAt) <= now()) return;
    ctx.sent.add(stage);
    const body = { traceId: ctx.block.traceId, attemptId: ctx.attemptId, stage, workerBuild, workerRevision };
    for (const key of ['hasTarget','hasEvent','hasClient','ok']) if (typeof flags[key] === 'boolean') body[key] = flags[key];
    const work = (async () => {
      const controller = new AbortController();
      let timer;
      try {
        // Race as well as abort: a broken fetch must not hold the event forever.
        const response = await Promise.race([
          Promise.resolve().then(() => send(endpoint, { method: 'POST', credentials: 'omit', cache: 'no-store', redirect: 'error',
            referrerPolicy: 'no-referrer', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ctx.block.receiptToken}` },
            body: JSON.stringify(body), signal: controller.signal })),
          new Promise(resolve => { timer = setTimeout(() => { controller.abort(); resolve(null); }, timeoutMs); }),
        ]);
        if (response && [400,401,404,410,413,429].includes(response.status)) {
          stopped.set(ctx.block.traceId, Date.parse(ctx.block.expiresAt));
          if (stopped.size > 100) stopped.delete(stopped.keys().next().value);
        }
      } catch { /* No retries, commercial interceptors, logs or exception export. */ }
      finally { clearTimeout(timer); }
    })().catch(() => {});
    const pending = events.get(event) || [];
    pending.push(work); events.set(event, pending);
  };
  const forTarget = target => {
    prune();
    return [...clicks.values()].find(ctx => ctx.target === target) || null;
  };
  return {
    begin, report,
    bind(ctx, target) { if (ctx && ctx.kind === 'click') ctx.target = target; },
    metadata(target, client) {
      const ctx = forTarget(target);
      if (!ctx) return {};
      if (typeof client?.id === 'string') ctx.clients.add(client.id);
      return { qaObservationAck: { traceId: ctx.block.traceId, attemptId: ctx.attemptId } };
    },
    posted(event, target) { report(event, forTarget(target), 'NAVIGATION_POSTED', { hasClient: true, ok: true }); },
    acknowledge(event) {
      const data = event.data;
      if (!data || !uuid(data.traceId) || !uuid(data.attemptId) || !['APP_TARGET_ACCEPTED','CARD_FOCUSED'].includes(data.stage)) return;
      const ctx = clicks.get(data.attemptId);
      if (!ctx || ctx.block.traceId !== data.traceId || !ctx.clients.has(event.source?.id)) return;
      report(event, ctx, data.stage, { hasTarget: true, ok: true });
    },
    failed(event) { const ctx = contexts.get(event); if (ctx?.kind === 'click') report(event, ctx, 'CLICK_FAILED', { ok: false }); },
    async flush(event) { await Promise.allSettled(events.get(event) || []); events.delete(event); },
  };
}
